  let h := m_vmmaps mo in
  let b := bv_unsigned (vm_brk h) in
  bv_unsigned (vm_start_brk h) <= b -> b < req < 2^64 ->
  brk_r_ok mo (Z_to_bv 64 req) r = true ->
  (r = vm_brk h) \/ (r = Z_to_bv 64 req /\ brk_grow_ok mo (Z_to_bv 64 req) (Z_to_bv 64 req) = true).
