Lemma nstep_mmap_fixed_inv : forall a mo rsp mo' evs,
  let h := m_vmmaps mo in
  let aw := Z_to_bv 64 a in let n := Z_to_bv 64 PGSZ in
  0 < a -> a + PGSZ <= alloc_top h -> a mod 4096 = 0 ->
  region_free (vm_reserved h) aw n = true -> map_contains (vm_maps h) aw n = true ->
  nstep (NMmap a PGSZ PROT_NONE MAPFX) mo rsp mo' evs ->
  evs = [] /\ vm_only mo mo' /\
  exists x, dec_mmap_fixed a PGSZ rsp = Some x /\
  match x with
  | FxKept e => e = ENOMEM /\ mo' = mo
  | FxDone => m_vmmaps mo' = mkVmMapsFull (vm_reserved h) (vm_maps h)
                                         ((aw, n) :: maps_subtract (vm_noaccess h) a (a + PGSZ))
                                         (vm_start_brk h) (vm_brk h) (vm_limit h) (vm_mmap_base h) (vm_init_sp h)
  | FxLost e => e = ENOMEM /\ m_vmmaps mo' = mkVmMapsFull (vm_reserved h)
                                           (maps_subtract (vm_maps h) a (a + PGSZ))
                                           (maps_subtract (vm_noaccess h) a (a + PGSZ))
                                           (vm_start_brk h) (vm_brk h) (vm_limit h) (vm_mmap_base h) (vm_init_sp h)
  end.
Proof.
  intros a mo rsp mo' evs h aw n Ha Hc Hal Hrf Hmc H.
  pose proof (alloc_top_lt64 h) as Hcl.
  pose proof (nstep_mm_vm_only (NMmap a PGSZ PROT_NONE MAPFX) mo rsp mo' evs I H) as [Hv ->]. split; [reflexivity|]. split; [exact Hv|].
  apply nstep_mmap_iff in H as (_ & H & _). destruct rsp as [r ws zs us cs ci]. unfold check_mmap in H.
  rewrite w_is0_lit in H by (unfold PGSZ; lia). change (PGSZ =? 0) with false in H.
  change (mmap_off_aligned_b (Z_to_bv 64 0)) with true in H. change (mmap_anon_b (Z_to_bv 64 MAPFX)) with true in H. cbn [negb] in H.
  change (mmap_modeled_b (Z_to_bv 64 PROT_NONE) (Z_to_bv 64 MAPFX) (Z_to_bv 64 0)) with false in H.
  change (mmap_noaccess_b (Z_to_bv 64 PROT_NONE) (Z_to_bv 64 MAPFX) (Z_to_bv 64 0)) with false in H.
  change (mmap_fixed_noaccess_b (Z_to_bv 64 PROT_NONE) (Z_to_bv 64 MAPFX) (Z_to_bv 64 0)) with true in H.
  cbv iota beta in H. fold aw h in H. rewrite (unsigned_lit PGSZ) in H by (unfold PGSZ; lia).
  change (page_round_up_Z PGSZ) with PGSZ in H. fold n in H.
  assert (Haw : bv_unsigned aw = a) by (subst aw; apply unsigned_lit; unfold PGSZ in *; lia). rewrite Haw in H.
  replace (two_pow_64 <=? a + PGSZ) with false in H by (symmetry; apply Z.leb_gt; unfold two_pow_64, PGSZ in *; lia).
  replace (a + PGSZ <=? alloc_top h) with true in H by (symmetry; apply Z.leb_le; lia). cbn [negb] in H.
  rewrite page_size_eq, Hal in H. cbn [Z.eqb negb] in H.
  replace (0 <? a) with true in H by (symmetry; apply Z.ltb_lt; lia). cbn [negb] in H.
  cbv zeta in H. fold n in H. rewrite Hrf, Hmc in H. cbn [andb] in H.
  assert (Hn : bv_unsigned n = PGSZ) by (subst n; apply unsigned_lit; unfold PGSZ; lia). rewrite Hn in H.
  change (mmap_len PGSZ) with PGSZ. fold n. clear Haw Hn.
  destruct ws; [|discriminate]. destruct zs; [|discriminate]. destruct cs; [|destruct us; discriminate]. destruct ci; [|destruct us; discriminate].
  case_errno_in_eqn H Herr.
  - apply errno_ret_in_true in Herr as (e & He & ->). destruct He as [<-|[]].
    assert (Hd0 : errno_of (errno_ret ENOMEM) = Some ENOMEM) by (apply errno_of_errno_ret; unfold ENOMEM; lia).
    destruct us as [|u us].
    + injection H as <-. exists (FxKept ENOMEM). split; [|split; reflexivity].
      unfold dec_mmap_fixed. rewrite Hd0. reflexivity.
    + destruct (listNN_eqb (u :: us) [(aw, n)]) eqn:E; [|discriminate]. injection H as <-.
      apply listNN_eqb_eq in E. rewrite E. exists (FxLost ENOMEM). split.
      * unfold dec_mmap_fixed. subst aw n. rewrite !bv_eqb_refl. cbn [andb].
        change (mmap_len PGSZ) with PGSZ. rewrite ?bv_eqb_refl. cbn [andb]. rewrite Hd0. reflexivity.
      * split; [reflexivity|]. rewrite m_vmmaps_with_mmap_destroyed. unfold mmap_fixed_destroyed_next.
        assert (Haw : bv_unsigned aw = a) by (subst aw; apply unsigned_lit; unfold PGSZ in *; lia).
        assert (Hn : bv_unsigned n = PGSZ) by (subst n; apply unsigned_lit; unfold PGSZ; lia).
        rewrite Haw, Hn. reflexivity.
  - destruct (bv_eqb r aw && listNN_eqb us [(aw, n)]) eqn:E; [|discriminate]. inversion H; subst.
    apply andb_prop in E as [E1 E2]. apply bv_eqb_eq in E1. apply listNN_eqb_eq in E2. subst r us.
    exists FxDone. split; [|reflexivity].
    unfold dec_mmap_fixed. subst aw n. rewrite !bv_eqb_refl. cbn [andb].
    change (mmap_len PGSZ) with PGSZ. rewrite ?bv_eqb_refl. cbn [andb].
    rewrite errno_of_lit by (unfold PGSZ in *; lia). reflexivity.
Qed.

Ltac kl_open HK := destruct HK as [Kminv Khalt Kwf Kresv Krt Kstart Kgr Kme Kdis Kreg Kph Katop].
(* [comment removed for export] *)
Ltac katop K :=
  lazymatch goal with
  | |- ld_atop _ = alloc_top _ =>
      unfold alloc_top in K |- *;
      cbn [vm_init_sp brk_model_next mmap_fixed_rw_next mmap_fixed_noaccess_span_next mmap_fixed_destroyed_next mmap_fixed_rw_span_next] in *;
      first [exact K | congruence | lia]
  end.

